    INSERT INTO [dbo].[Products] ([Id], [CategoryId], [StyleId], [Name], [Slug], [Sku], [ShortDescription], [Description], [FurnitureType], [Status], [BasePrice], [DiscountPrice], [StockQuantity], [IsFeatured], [SoldCount], [ViewCount], [AverageRating], [ReviewCount], [LengthMm], [WidthMm], [HeightMm], [WeightKg], [WarrantyMonths], [Origin], [CareInstructions], [MetaTitle], [MetaDescription], [PublishedAt], [IsDeleted], [DeletedAt], [DeletedBy], [Version], [CreatedAt], [CreatedBy], [UpdatedAt], [UpdatedBy], [SearchText]) VALUES (1, 6, 6, N'Sofa băng 3 chỗ Oslo khung gỗ sồi', N'sofa-bang-3-cho-oslo-khung-go-soi', N'SF-OSLO', N'Sofa 3 chỗ phong cách Bắc Âu, khung gỗ sồi tự nhiên, đệm mút D40 bọc vải bố tháo giặt được.', N'Sofa Oslo mang tinh thần tối giản Bắc Âu với tay vịn bo tròn và chân gỗ sồi vát côn.
Khung làm từ gỗ sồi sấy đạt độ ẩm 10 - 12%, liên kết mộng chắc chắn, không ọp ẹp sau nhiều năm sử dụng.
Đệm ngồi mút D40 kết hợp lò xo túi cho độ êm vừa phải; vỏ vải bố dệt dày có khóa kéo để tháo giặt.', N'Sofa', N'Active', 16900000.00, NULL, 77, 1, 86, 1072, 3.00, 1, 2100, 850, 800, 58.00, 24, N'Việt Nam - Xưởng Nhà Mộc', N'Hút bụi định kỳ 1 - 2 lần/tuần; thấm vết bẩn bằng khăn ẩm, không chà mạnh. Vỏ đệm tháo rời nên giặt khô.', N'Sofa băng 3 chỗ Oslo khung gỗ sồi', N'Sofa 3 chỗ phong cách Bắc Âu, khung gỗ sồi tự nhiên, đệm mút D40 bọc vải bố tháo giặt được.', '2026-10-06T09:48:38.8112402', 0, NULL, NULL, 'aa811578-c097-49c2-9a47-e1ebcc194bf1', '2026-10-07T09:48:39.1483308', N'system', NULL, NULL, N'sofa bang 3 cho oslo khung go soi sf oslo sofa phong khach bac au vai bo go soi kem be xam xanh reu');
