    INSERT INTO [dbo].[Products] ([Id], [CategoryId], [StyleId], [Name], [Slug], [Sku], [ShortDescription], [Description], [FurnitureType], [Status], [BasePrice], [DiscountPrice], [StockQuantity], [IsFeatured], [SoldCount], [ViewCount], [AverageRating], [ReviewCount], [LengthMm], [WidthMm], [HeightMm], [WeightKg], [WarrantyMonths], [Origin], [CareInstructions], [MetaTitle], [MetaDescription], [PublishedAt], [IsDeleted], [DeletedAt], [DeletedBy], [Version], [CreatedAt], [CreatedBy], [UpdatedAt], [UpdatedBy], [SearchText]) VALUES (42, 22, 8, N'Kệ trang trí treo tường gỗ thông', N'ke-trang-tri-treo-tuong-go-thong', N'KTT-PINE', N'Kệ treo tường 3 tầng gỗ thông tự nhiên, trang trí cây xanh và sách nhỏ.', N'Gỗ thông giữ vân mắt tự nhiên, xử lý chống mối mọt; đi kèm vít nở và hướng dẫn lắp đặt.', N'Shelf', N'Active', 890000.00, NULL, 43, 0, 205, 2500, 5.00, 2, 800, 200, 600, 5.00, 12, N'Việt Nam - Xưởng Nhà Mộc', N'Lau bằng khăn mềm hơi ẩm rồi lau khô; tránh ánh nắng trực tiếp, nguồn nhiệt và hóa chất tẩy rửa mạnh. Dùng lót cốc khi đặt đồ nóng hoặc lạnh.', N'Kệ trang trí treo tường gỗ thông', N'Kệ treo tường 3 tầng gỗ thông tự nhiên, trang trí cây xanh và sách nhỏ.', '2026-09-19T09:48:38.8112402', 0, NULL, NULL, '990e486e-dcfc-4aaa-94ce-aa6724f0de82', '2026-10-07T09:48:39.1483308', N'system', NULL, NULL, N'ke trang tri treo tuong go thong ktt pine ke trang tri trang tri tien ich moc mac ke go thong mau go tu nhien nau oc cho');
    INSERT INTO [dbo].[Products] ([Id], [CategoryId], [StyleId], [Name], [Slug], [Sku], [ShortDescription], [Description], [FurnitureType], [Status], [BasePrice], [DiscountPrice], [StockQuantity], [IsFeatured], [SoldCount], [ViewCount], [AverageRating], [ReviewCount], [LengthMm], [WidthMm], [HeightMm], [WeightKg], [WarrantyMonths], [Origin], [CareInstructions], [MetaTitle], [MetaDescription], [PublishedAt], [IsDeleted], [DeletedAt], [DeletedBy], [Version], [CreatedAt], [CreatedBy], [UpdatedAt], [UpdatedBy], [SearchText]) VALUES (43, 23, 7, N'Gương đứng khung gỗ óc chó mái vòm', N'guong-dung-khung-go-oc-cho-mai-vom', N'GU-ARCH', N'Gương soi toàn thân mái vòm, khung gỗ óc chó, có chân đỡ đứng hoặc treo tường.', N'Mặt gương bạc Bỉ không biến dạng hình ảnh, khung gỗ óc chó bo vòm mềm mại; dùng đứng hoặc treo tường đều được.', N'Decor', N'Active', 3200000.00, NULL, 17, 0, 67, 844, 4.00, 1, 600, 40, 1700, 15.00, 12, N'Việt Nam - Xưởng Nhà Mộc', N'Lau bằng khăn mềm hơi ẩm rồi lau khô; tránh ánh nắng trực tiếp, nguồn nhiệt và hóa chất tẩy rửa mạnh. Dùng lót cốc khi đặt đồ nóng hoặc lạnh.', N'Gương đứng khung gỗ óc chó mái vòm', N'Gương soi toàn thân mái vòm, khung gỗ óc chó, có chân đỡ đứng hoặc treo tường.', '2026-09-12T09:48:38.8112402', 0, NULL, NULL, '9c8da88a-89da-48af-ac93-3e30b19b3bae', '2026-10-07T09:48:39.1483308', N'system', NULL, NULL, N'guong dung khung go oc cho mai vom gu arch guong trang tri tien ich japandi trang tri go oc cho kinh cuong luc nau oc cho');
